"""
Script de fusion des 3 pieves Plaine Orientale :
1. bozio (PO) -> alesani  : reconfigurer bozio Cortenais-only + etendre alesani
2. fiumorbo + zone verde  : etendre fiumorbo vers le sud (ancienne pieve_verde)
3. moriani + campoloro    : etendre moriani vers le sud (ancienne pieve_campoloro)
"""

import json
from shapely.geometry import Polygon, box
from shapely.ops import unary_union

TOLERANCE = 0.0005  # meme tolerance que le JSON original

def to_shapely(coords):
    """[lat, lon] list -> shapely Polygon (lon, lat)"""
    return Polygon([(c[1], c[0]) for c in coords])

def from_shapely(poly, decimals=5):
    """shapely Polygon (lon, lat) -> [[lat, lon]] list"""
    coords = list(poly.exterior.coords)
    return [[round(c[1], decimals), round(c[0], decimals)] for c in coords[:-1]]

def simplify_and_convert(union_poly, tolerance=TOLERANCE):
    """Simplifier + convertir en format JSON [lat,lon]"""
    simplified = union_poly.simplify(tolerance, preserve_topology=True)
    if simplified.geom_type == 'MultiPolygon':
        # Prendre la plus grande partie
        largest = max(simplified.geoms, key=lambda g: g.area)
        print(f"  ATTENTION: MultiPolygon -> partie la plus grande ({largest.area:.4f})")
        simplified = largest
    return from_shapely(simplified)

