def main():
    with open('docs/data/pieves_polygons.json', encoding='utf-8') as f:
        data = json.load(f)

    pieves_list = data['pieves']
    pieves = {p['slug']: p for p in pieves_list}

    # --------------------------------------------------------
    # FUSION 1 : bozio (PO) -> alesani
    # Etendre alesani pour couvrir la zone bozio-PO.
    # Reconfigurer bozio en Cortenais-only (les 13 sites Cortenais restent).
    # --------------------------------------------------------
    print("=== Fusion 1 : bozio -> alesani ===")
    bozio_s = to_shapely(pieves['pieve_bozio']['polygon'])
    alesani_s = to_shapely(pieves['pieve_alesani']['polygon'])
    new_alesani = unary_union([alesani_s, bozio_s])
    print(f"  alesani avant: {len(pieves['pieve_alesani']['polygon'])} pts")
    print(f"  union type: {new_alesani.geom_type}, valide: {new_alesani.is_valid}")
    new_alesani_coords = simplify_and_convert(new_alesani)
    print(f"  alesani apres: {len(new_alesani_coords)} pts")
    lats = [c[0] for c in new_alesani_coords]
    print(f"  alesani lat range: {min(lats):.3f} to {max(lats):.3f}")

    # Modifier pieve_alesani
    for p in pieves_list:
        if p['slug'] == 'pieve_alesani':
            p['polygon'] = new_alesani_coords
            break

    # Reconfigurer bozio en Cortenais-only
    for p in pieves_list:
        if p['slug'] == 'pieve_bozio':
            p['doyenne_contemporain_majoritaire'] = 'doyenne_cortenais'
            p['doyennes_appartenance'] = [{'slug': 'doyenne_cortenais', 'ratio': 1.0}]
            # doyennes_visibles reste ['doyenne_cortenais']
            break
    print("  bozio reconfigure Cortenais-only")

    # --------------------------------------------------------
    # FUSION 2 : fiumorbo + zone verde (nord) -> fiumorbo elargi
    # Etendre fiumorbo vers le sud pour couvrir les 8 sites ex-verde.
    # Cliper verde au nord (lat > 41.75) pour ne pas descendre en Extreme-Sud.
    # --------------------------------------------------------
    print("\n=== Fusion 2 : fiumorbo + zone verde-nord ===")
    fiumorbo_s = to_shapely(pieves['pieve_fiumorbo']['polygon'])
    verde_s = to_shapely(VERDE_POLYGON)
    # Clip verde au nord seulement (lat 41.75-42.05) pour eviter Extreme-Sud profond
    clip_north = box(8.5, 41.75, 9.7, 42.1)  # (minx, miny, maxx, maxy) = (minlon, minlat, maxlon, maxlat)
    verde_north = verde_s.intersection(clip_north)
    print(f"  verde_north type: {verde_north.geom_type}, valide: {verde_north.is_valid}")
    new_fiumorbo = unary_union([fiumorbo_s, verde_north])
    print(f"  fiumorbo avant: {len(pieves['pieve_fiumorbo']['polygon'])} pts")
    print(f"  union type: {new_fiumorbo.geom_type}, valide: {new_fiumorbo.is_valid}")
    new_fiumorbo_coords = simplify_and_convert(new_fiumorbo)
    print(f"  fiumorbo apres: {len(new_fiumorbo_coords)} pts")
    lats = [c[0] for c in new_fiumorbo_coords]
    print(f"  fiumorbo lat range: {min(lats):.3f} to {max(lats):.3f}")

    for p in pieves_list:
        if p['slug'] == 'pieve_fiumorbo':
            p['polygon'] = new_fiumorbo_coords
            break

    # --------------------------------------------------------
    # FUSION 3 : moriani + campoloro -> moriani elargi
    # --------------------------------------------------------
    print("\n=== Fusion 3 : moriani + campoloro ===")
    moriani_s = to_shapely(pieves['pieve_moriani']['polygon'])
    campoloro_s = to_shapely(CAMPOLORO_POLYGON)
    new_moriani = unary_union([moriani_s, campoloro_s])
    print(f"  moriani avant: {len(pieves['pieve_moriani']['polygon'])} pts")
    print(f"  union type: {new_moriani.geom_type}, valide: {new_moriani.is_valid}")
    new_moriani_coords = simplify_and_convert(new_moriani)
    print(f"  moriani apres: {len(new_moriani_coords)} pts")
    lats = [c[0] for c in new_moriani_coords]
    print(f"  moriani lat range: {min(lats):.3f} to {max(lats):.3f}")

    for p in pieves_list:
        if p['slug'] == 'pieve_moriani':
            p['polygon'] = new_moriani_coords
            break

    # Mise a jour stats
    data['stats']['pieves_count'] = len(pieves_list)

    # Ecrire le JSON
    with open('docs/data/pieves_polygons.json', 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(f"\nJSON ecrit. Total pieves: {len(pieves_list)} (inchange, bozio reste pour Cortenais)")

    # Verifications finales
    print("\n=== Verifications ===")
    with open('docs/data/pieves_polygons.json', encoding='utf-8') as f:
        check = json.load(f)
    po_pieves = [p for p in check['pieves'] if p.get('doyenne_contemporain_majoritaire') == 'doyenne_plaine_orientale']
    print(f"Pieves avec doyenne_contemporain_majoritaire=PO: {len(po_pieves)}")
    for p in po_pieves:
        print(f"  {p['slug']} | {p.get('name')}")
    bozio_check = next(p for p in check['pieves'] if p['slug'] == 'pieve_bozio')
    print(f"\nbozio doyenne_majoritaire: {bozio_check['doyenne_contemporain_majoritaire']}")
    print(f"bozio doyennes_appartenance: {bozio_check['doyennes_appartenance']}")

if __name__ == '__main__':
    main()
